     2|import path from 'node:path';
     3|import { writeFile, readFile, mkdir, rm } from 'node:fs/promises';
     4|import { existsSync } from 'node:fs';
     5|import os from 'node:os';
     6|import {
     7|  buildAutonomousCoderAnswer,
     8|  runIVXAutonomousCoder,
     9|  isPilotLabelChangeGoal,
    10|  IVX_AUTONOMOUS_CODER_MARKER,
    11|  type IVXAutonomousCoderInput,
    12|  type IVXAutonomousCoderTestResult,
    13|} from './services/ivx-autonomous-coder';
    14|import { PILOT_LABEL, PILOT_LABEL_TARGET, describePilotSentinel } from './services/ivx-autonomous-coder-pilot';
    15|
    16|const TMP_ROOT = path.join(os.tmpdir(), `ivx-ac-test-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
    17|
    18|beforeAll(async () => {
    19|  await mkdir(TMP_ROOT, { recursive: true });
    20|});
    21|
    22|afterAll(async () => {
    23|  await rm(TMP_ROOT, { recursive: true, force: true }).catch(() => {});
    24|});
    25|
    26|/** Create an isolated project root with a pilot sentinel file for one test. */
    27|async function makeIsolatedRepo(label: string): Promise<{
    28|  root: string;
    29|  fileWriter: (rel: string, content: string) => Promise<void>;
    30|  fileReader: (rel: string) => Promise<string>;
    31|}> {
    32|  const root = path.join(TMP_ROOT, label);
    33|  await mkdir(path.join(root, 'backend/services'), { recursive: true });
    34|  const pilotContent = `export const PILOT_LABEL = '${PILOT_LABEL}';\nexport const PILOT_LABEL_TARGET = '${PILOT_LABEL_TARGET}';\n`;
    35|  await writeFile(path.join(root, 'backend/services/ivx-autonomous-coder-pilot.ts'), pilotContent, 'utf8');
    36|  const fileWriter = async (rel: string, content: string) => {
    37|    await mkdir(path.dirname(path.join(root, rel)), { recursive: true });
    38|    await writeFile(path.join(root, rel), content, 'utf8');
    39|  };
    40|  const fileReader = async (rel: string) => readFile(path.join(root, rel), 'utf8');
    41|  return { root, fileWriter, fileReader };
    42|}
    43|
    44|describe('IVX Autonomous Coder — pilot sentinel', () => {
    45|  it('exposes the pilot label and target', () => {
    46|    const sentinel = describePilotSentinel();
    47|    expect(sentinel.label).toBe('AUTONOMOUS-CODER-PILOT-1');
    48|    expect(sentinel.target).toBe('AUTONOMOUS-CODER-PILOT-2');
    49|    expect(sentinel.file).toBe('backend/services/ivx-autonomous-coder-pilot.ts');
    50|    expect(PILOT_LABEL).toBe('AUTONOMOUS-CODER-PILOT-1');
    51|    expect(PILOT_LABEL_TARGET).toBe('AUTONOMOUS-CODER-PILOT-2');
    52|  });
    53|});
    54|
    55|describe('IVX Autonomous Coder — engine loop', () => {
    56|  it('runs the full INSPECT→PLAN→PATCH→TEST→COMMIT loop with injected LLM + test runner + commit fn', async () => {
    57|    const repo = await makeIsolatedRepo('test-001');
    58|
    59|    const llmCaller = async () => JSON.stringify({
    60|      rootCause: 'Pilot label still at PILOT-1; needs bump to PILOT-2.',
    61|      technicalPlan: 'replace_exact on the PILOT_LABEL string.',
    62|      operations: [
    63|        {
    64|          path: 'backend/services/ivx-autonomous-coder-pilot.ts',
    65|          kind: 'replace_exact',
    66|          oldText: `export const PILOT_LABEL = '${PILOT_LABEL}';`,
    67|          newText: `export const PILOT_LABEL = '${PILOT_LABEL_TARGET}';`,
    68|          reason: 'Bump the pilot sentinel.',
    69|        },
    70|      ],
    71|    });
    72|
    73|    const testRunner = async (_cwd: string, command: string): Promise<IVXAutonomousCoderTestResult> => ({
    74|      command, ok: true, exitCode: 0, stdoutTail: 'all tests passed', stderrTail: '', durationMs: 10,
    75|    });
    76|
    77|    const commitFn = async (_filePaths: string[], _branch: string) => ({
    78|      commitSha: 'fake-commit-sha-abc123',
    79|      commitUrl: 'https://github.com/ibb142/ivx-holdings-platform/commit/fake-commit-sha-abc123',
    80|      branch: 'main',
    81|    });
    82|
    83|    const input: IVXAutonomousCoderInput = {
    84|      taskId: 'ivx-ac-test-001',
    85|      goal: `Change the pilot label from ${PILOT_LABEL} to ${PILOT_LABEL_TARGET}. Run targeted tests, typecheck, create a commit, but do not deploy.`,
    86|      executionMode: 'code_change',
    87|      ownerId: 'test-owner',
    88|      approvalPolicy: 'owner_gated',
    89|      projectRoot: repo.root,
    90|      fileWriter: repo.fileWriter,
    91|      fileReader: repo.fileReader,
    92|      llmCaller,
    93|      testRunner,
    94|      commitFn,
    95|    };
    96|
    97|    const proof = await runIVXAutonomousCoder(input);
    98|
    99|    expect(proof.marker).toBe(IVX_AUTONOMOUS_CODER_MARKER);
   100|    expect(proof.taskId).toBe('ivx-ac-test-001');
   101|    expect(proof.executionMode).toBe('code_change');
   102|    expect(proof.patchAuthoredBy).toBe('ivx_llm');
   103|    expect(proof.iterations.length).toBeGreaterThanOrEqual(1);
   104|    expect(proof.iterations[0].patchGenerated).toBe(true);
   105|    expect(proof.iterations[0].patchApplied).toBe(true);
   106|    expect(proof.iterations[0].testsPassed).toBe(true);
