     2| * IVX Landing Payment Sync Service
     3| *
     4| * Ensures that every landing-page "Invest Now" intent becomes a REAL payment
     5| * transaction that is visible inside the app admin payment transactions view.
     6| *
     7| * Rules:
     8| *   - No simulated/fake transactions in production.
     9| *   - Every landing investment creates a pending payment transaction in the
    10| *     `transactions` table and a linked `landing_investments` record.
    11| *   - Every create/update is appended to the durable audit log.
    12| *   - If no real payment provider is configured, the transaction stays in
    13| *     `pending_payment` status awaiting owner review / wire confirmation.
    14| */
    15|
    16|import { createClient, type SupabaseClient } from '@supabase/supabase-js';
    17|import { randomUUID } from 'node:crypto';
    18|import { mkdir, appendFile } from 'node:fs/promises';
    19|import path from 'node:path';
    20|import { auditDir } from './ivx-data-root';
    21|
    22|const DEPLOYMENT_MARKER = 'ivx-landing-payment-sync-v1-real-only';
    23|
    24|const AUDIT_DIR = auditDir('landing-payment-sync');
    25|const AUDIT_LOG_FILE = () => path.join(AUDIT_DIR, 'audit.jsonl');
    26|
    27|export interface LandingPaymentInput {
    28|  dealId: string;
    29|  dealTitle: string;
    30|  investmentType: 'jv_direct' | 'token_shares' | string;
    31|  amount: number;
    32|  expectedRoi?: number;
    33|  ownershipPct?: number;
    34|  paymentMethod: 'bank' | 'wire' | 'wallet' | string;
    35|  investorEmail: string;
    36|  investorId?: string | null;
    37|  investorName?: string;
    38|  termsAccepted: boolean;
    39|  source: string;
    40|  ip?: string;
    41|  userAgent?: string;
    42|}
    43|
    44|export interface LandingPaymentResult {
    45|  success: boolean;
    46|  transactionId: string;
    47|  landingInvestmentId: string;
    48|  intentId: string;
    49|  status: 'pending_payment' | 'pending' | 'completed' | 'failed';
    50|  message: string;
    51|  providerConfigured: boolean;
    52|  providerMode?: 'live' | 'test' | 'none';
    53|  auditLogged: boolean;
    54|  deploymentMarker: string;
    55|  error?: string;
    56|}
    57|
    58|function getSupabaseAdmin(): SupabaseClient {
    59|  const url =
    60|    process.env.SUPABASE_URL ||
    61|    process.env.EXPO_PUBLIC_SUPABASE_URL ||
    62|    '';
    63|  const key =
    64|    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    65|    process.env.SUPABASE_SERVICE_KEY ||
    66|    process.env.SUPABASE_ANON_KEY ||
    67|    process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ||
    68|    '';
    69|  return createClient(url, key, {
    70|    auth: { persistSession: false, autoRefreshToken: false },
    71|  });
    72|}
    73|
    74|function isProviderConfigured(): { configured: boolean; mode: 'live' | 'test' | 'none' } {
    75|  const stripeLive = Boolean(process.env.STRIPE_SECRET_KEY && !process.env.STRIPE_SECRET_KEY.includes('test'));
    76|  const stripeTest = Boolean(process.env.STRIPE_SECRET_KEY && process.env.STRIPE_SECRET_KEY.includes('test'));
    77|  const plaidProduction = Boolean(process.env.PLAID_SECRET && process.env.PLAID_ENV === 'production');
    78|  const plaidTest = Boolean(process.env.PLAID_SECRET && process.env.PLAID_ENV !== 'production');
    79|  const paypalLive = Boolean(process.env.PAYPAL_CLIENT_SECRET && process.env.PAYPAL_ENV === 'live');
    80|
    81|  if (stripeLive || plaidProduction || paypalLive) return { configured: true, mode: 'live' };
    82|  if (stripeTest || plaidTest) return { configured: true, mode: 'test' };
    83|  return { configured: false, mode: 'none' };
    84|}
