     1|/**
     2| * IVX Landing Payment Sync Service
     3| *
     4| * Ensures that every landing-page "Invest Now" intent becomes a REAL payment
     5| * transaction that is visible inside the app admin payment transactions view.
     6| *
     7| * Rules:
     8| *   - No simulated/fake transactions in production.
     9| *   - Every landing investment creates a pending payment transaction in the
    10| *     `transactions` table and a linked `landing_investments` record.
    11| *   - Every create/update is appended to the durable audit log.
    12| *   - If no real payment provider is configured, the transaction stays in
    13| *     `pending_payment` status awaiting owner review / wire confirmation.
    14| */
    15|
    16|import { createClient, type SupabaseClient } from '@supabase/supabase-js';
    17|import { randomUUID } from 'node:crypto';
    18|import { mkdir, appendFile } from 'node:fs/promises';
    19|import path from 'node:path';
    20|import { auditDir } from './ivx-data-root';
    21|
    22|const DEPLOYMENT_MARKER = 'ivx-landing-payment-sync-v1-real-only';
    23|
    24|const AUDIT_DIR = auditDir('landing-payment-sync');
    25|const AUDIT_LOG_FILE = () => path.join(AUDIT_DIR, 'audit.jsonl');
    26|
    27|export interface LandingPaymentInput {
    28|  dealId: string;
    29|  dealTitle: string;
    30|  investmentType: 'jv_direct' | 'token_shares' | string;
    31|  amount: number;
    32|  expectedRoi?: number;
